import { useMemo, useRef, useState } from "react"
import { useHotkeys } from "react-hotkeys-hook"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import {
  aggregateLabel,
  aggregateUnit,
  buildChart,
  buildGroups,
  defaultQuery,
  fieldByKey,
  maxOf,
  normalizeQuery,
  sameQuery,
  sortSamples,
} from "./aggregate"
import { QueryRail } from "./query-rail"
import { ResultsTable } from "./results-table"
import { SeriesChart } from "./series-chart"
import type {
  AggregateQuery,
  AggregateRow,
  FieldSchema,
  GroupSortBy,
  ResultsTab,
} from "./types"

// the chart is role=slider and the line/bar toggle is role=radio; the hook skips both unless listed
const KEY_TARGET_ROLES = ["slider", "radio"] as const

export type AggregateBuilderProps<T extends AggregateRow> = {
  rows: T[]
  schema: FieldSchema
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  /** Controlled query; omit for internal state. */
  query?: AggregateQuery
  onQueryChange?: (query: AggregateQuery) => void
  /** Starting point for internal state and for Reset. */
  initialQuery?: Partial<AggregateQuery>
  /** Controlled tab; omit for internal state (starts on "samples"). */
  tab?: ResultsTab
  onTabChange?: (tab: ResultsTab) => void
  /** Makes each sample's ID a button that calls this. */
  onOpenRow?: (row: T) => void
  sampleLimit?: number
  emptyTitle?: string
  emptyAction?: { label: string; onClick: () => void }
  "aria-label"?: string
}

/**
 * A rail of Visualize, Group by and Sort by controls driving a chart over time buckets and a
 * Samples / Aggregates table. Aggregation is pure over `rows` and `schema`; the block never reads
 * a store.
 */
export function AggregateBuilder<T extends AggregateRow>({
  rows,
  schema,
  status = "ready",
  error,
  onRetry,
  query: controlledQuery,
  onQueryChange,
  initialQuery,
  tab: controlledTab,
  onTabChange,
  onOpenRow,
  sampleLimit = 100,
  emptyTitle = "No rows to chart",
  emptyAction,
  "aria-label": ariaLabel = "Aggregate builder",
}: AggregateBuilderProps<T>) {
  const rootRef = useRef<HTMLDivElement>(null)
  const aggregateRef = useRef<HTMLButtonElement>(null)
  const groupRef = useRef<HTMLButtonElement>(null)
  const sortRef = useRef<HTMLButtonElement>(null)

  const base = normalizeQuery({ ...defaultQuery(schema), ...initialQuery }, schema)
  const [internalQuery, setInternalQuery] = useState(base)
  const [internalTab, setInternalTab] = useState<ResultsTab>("samples")
  const rawQuery = controlledQuery ?? internalQuery
  const query = useMemo(() => normalizeQuery(rawQuery, schema), [rawQuery, schema])
  const tab = controlledTab ?? internalTab

  const update = (patch: Partial<AggregateQuery>) => {
    const next = normalizeQuery({ ...query, ...patch }, schema)
    setInternalQuery(next)
    onQueryChange?.(next)
  }
  const changeTab = (next: ResultsTab) => {
    setInternalTab(next)
    onTabChange?.(next)
  }

  const onSort = (by: string) => {
    if (tab === "samples") {
      const same = query.sampleSort.by === by
      const kind = fieldByKey(schema, by)?.kind
      update({
        sampleSort: {
          by,
          dir: same
            ? query.sampleSort.dir === "asc" ? "desc" : "asc"
            : kind === "text" ? "asc" : "desc",
        },
      })
    } else {
      const same = query.groupSort.by === by
      update({
        groupSort: {
          by: by as GroupSortBy,
          dir: same
            ? query.groupSort.dir === "asc" ? "desc" : "asc"
            : by === "group" ? "asc" : "desc",
        },
      })
    }
  }

  const ready = status === "ready" && rows.length > 0
  const groupingApplies = tab === "aggregates" && query.groupBy !== null

  const samples = useMemo(
    () => sortSamples(rows, query.sampleSort, schema),
    [rows, query.sampleSort, schema]
  )
  const groups = useMemo(
    () => buildGroups(rows, { ...query, groupBy: tab === "aggregates" ? query.groupBy : null }),
    [rows, query, tab]
  )
  const chart = useMemo(
    () => buildChart(rows, query, schema, groups),
    [rows, query, schema, groups]
  )
  const barMax = schema.barField ? maxOf(rows, schema.barField) : 0

  const inScope = (event: KeyboardEvent) => {
    const target = event.target
    if (target === document.body || target === document.documentElement) return true
    return target instanceof Node && rootRef.current?.contains(target) === true
  }
  useHotkeys(
    "v",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      aggregateRef.current?.focus()
    },
    { enabled: ready, enableOnFormTags: KEY_TARGET_ROLES }
  )
  useHotkeys(
    "g",
    (event) => {
      if (!inScope(event) || tab !== "aggregates") return
      event.preventDefault()
      groupRef.current?.focus()
    },
    { enabled: ready, enableOnFormTags: KEY_TARGET_ROLES }
  )
  useHotkeys(
    "s",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      sortRef.current?.focus()
    },
    { enabled: ready, enableOnFormTags: KEY_TARGET_ROLES }
  )
  useHotkeys(
    "1,2",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      changeTab(event.key === "1" ? "samples" : "aggregates")
    },
    { enabled: ready, enableOnFormTags: KEY_TARGET_ROLES }
  )
  useHotkeys(
    "c",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      update({ chart: query.chart === "bar" ? "line" : "bar" })
    },
    { enabled: ready, enableOnFormTags: KEY_TARGET_ROLES }
  )

  const groupField = fieldByKey(schema, query.groupBy)
  const title = `${aggregateLabel(query.visualize, schema)}${
    groupingApplies && groupField ? ` by ${groupField.label.toLowerCase()}` : ""
  }`

  let results
  if (status === "loading") {
    results = <LoadingState label="Loading rows" />
  } else if (status === "error") {
    results = <ErrorState error={error ?? new Error("The rows could not be loaded.")} onRetry={onRetry} />
  } else if (rows.length === 0) {
    results = (
      <EmptyState
        title={emptyTitle}
        description="Rows appear here once the log has entries."
        action={
          emptyAction ? (
            <Button size="sm" variant="outline" onClick={emptyAction.onClick}>
              {emptyAction.label}
            </Button>
          ) : undefined
        }
      />
    )
  } else {
    results = (
      <>
        <SeriesChart
          model={chart}
          title={title}
          unit={aggregateUnit(query.visualize, schema)}
          query={query}
          onChange={update}
          noValuesLabel={`No values for ${aggregateLabel(query.visualize, schema)}`}
        />
        <ResultsTable
          tab={tab}
          onTabChange={changeTab}
          schema={schema}
          query={query}
          samples={samples}
          groups={groups}
          sampleLimit={sampleLimit}
          barMax={barMax}
          onSort={onSort}
          onOpenRow={onOpenRow}
        />
      </>
    )
  }

  return (
    <div
      ref={rootRef}
      role="region"
      aria-label={ariaLabel}
      className="@container h-full min-h-0 bg-background text-foreground"
    >
      <div
        className={cn(
          "grid h-full min-h-[30rem] grid-cols-1",
          "@2xl:grid-cols-[36%_minmax(0,1fr)]"
        )}
      >
        <div className="min-w-0 border-b @2xl:overflow-auto @2xl:border-r @2xl:border-b-0">
          <QueryRail
            schema={schema}
            query={query}
            tab={tab}
            disabled={status !== "ready"}
            canReset={!sameQuery(query, base)}
            onChange={update}
            onReset={() => update(base)}
            aggregateRef={aggregateRef}
            groupRef={groupRef}
            sortRef={sortRef}
          />
        </div>
        <div className="min-w-0 @2xl:overflow-auto">{results}</div>
      </div>
    </div>
  )
}

import type { Ref } from "react"

import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

import type { AggregateDef } from "./aggregate"
import { keepBlockKeys } from "./field-picker"
import type { AggregateFn } from "./types"

/** A select of aggregate functions, grouped as Count, Statistics and Percentiles. */
export function AggregatePicker({
  id,
  value,
  onChange,
  options,
  disabled,
  triggerRef,
}: {
  id?: string
  value: AggregateFn
  onChange: (fn: AggregateFn) => void
  options: AggregateDef[]
  disabled?: boolean
  triggerRef?: Ref<HTMLButtonElement>
}) {
  const groups = [...new Set(options.map((option) => option.group))]
  return (
    <Select
      value={value}
      onValueChange={(next) => onChange(next as AggregateFn)}
      disabled={disabled}
    >
      <SelectTrigger
        id={id}
        ref={triggerRef}
        size="sm"
        aria-label="Aggregate function"
        onKeyDown={keepBlockKeys}
        className="w-full min-w-0"
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {groups.map((group) => (
          <SelectGroup key={group}>
            <SelectLabel>{group}</SelectLabel>
            {options
              .filter((option) => option.group === group)
              .map((option) => (
                <SelectItem key={option.fn} value={option.fn}>
                  {option.label}
                </SelectItem>
              ))}
          </SelectGroup>
        ))}
      </SelectContent>
    </Select>
  )
}

import type {
  AggregateFn,
  AggregateQuery,
  AggregateRow,
  FieldDef,
  FieldSchema,
  SortDir,
  Visualize,
} from "./types"

export type AggregateDef = {
  fn: AggregateFn
  label: string
  group: "Count" | "Statistics" | "Percentiles"
  /** What field the function reads: none (count), any kind of field, or a number field. */
  needs: "none" | "any" | "number"
}

export const AGGREGATES: AggregateDef[] = [
  { fn: "count", label: "Count", group: "Count", needs: "none" },
  { fn: "count_unique", label: "Count unique", group: "Count", needs: "any" },
  { fn: "sum", label: "Sum", group: "Statistics", needs: "number" },
  { fn: "avg", label: "Average", group: "Statistics", needs: "number" },
  { fn: "min", label: "Minimum", group: "Statistics", needs: "number" },
  { fn: "max", label: "Maximum", group: "Statistics", needs: "number" },
  { fn: "p50", label: "p50 (median)", group: "Percentiles", needs: "number" },
  { fn: "p75", label: "p75", group: "Percentiles", needs: "number" },
  { fn: "p95", label: "p95", group: "Percentiles", needs: "number" },
  { fn: "p99", label: "p99", group: "Percentiles", needs: "number" },
]

/** Stroke dash per chart slot, so series stay distinct when chart colors are close. */
export const SERIES_DASHES: (string | undefined)[] = [undefined, "6 3", "2 3", "9 3 2 3", "1 4"]

export const NO_VALUE_LABEL = "(none)"
export const ALL_ROWS_LABEL = "All rows"
/** Chart series cap: the top four groups plus "Other" fill the five chart tokens. */
export const MAX_SERIES = 5

const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR
export const INTERVAL_PRESETS = [
  MINUTE,
  5 * MINUTE,
  15 * MINUTE,
  HOUR,
  3 * HOUR,
  6 * HOUR,
  12 * HOUR,
  DAY,
]
export const AUTO_BUCKETS = 60
export const MAX_BUCKETS = 240

export function aggregateDef(fn: AggregateFn): AggregateDef {
  return AGGREGATES.find((def) => def.fn === fn) ?? AGGREGATES[0]
}

export function fieldByKey(schema: FieldSchema, key: string | null | undefined) {
  return key ? schema.fields.find((field) => field.key === key) : undefined
}

/** Fields the function can read: none for count, any non-time field for count unique, number fields otherwise. */
export function fieldsFor(fn: AggregateFn, schema: FieldSchema): FieldDef[] {
  const { needs } = aggregateDef(fn)
  if (needs === "none") return []
  if (needs === "any") return schema.fields.filter((field) => field.kind !== "time")
  return schema.fields.filter((field) => field.kind === "number")
}

export function availableAggregates(schema: FieldSchema): AggregateDef[] {
  return AGGREGATES.filter(
    (def) => def.needs === "none" || fieldsFor(def.fn, schema).length > 0
  )
}

/** Keeps the field when it still applies to `fn`, otherwise takes the first that does. */
export function coerceVisualize(visualize: Visualize, schema: FieldSchema): Visualize {
  const available = availableAggregates(schema)
  const fn = available.some((def) => def.fn === visualize.fn)
    ? visualize.fn
    : "count"
  const candidates = fieldsFor(fn, schema)
  if (candidates.length === 0) return { fn }
  const field = candidates.some((f) => f.key === visualize.field)
    ? visualize.field
    : candidates[0].key
  return { fn, field }
}

export function defaultQuery(schema: FieldSchema): AggregateQuery {
  return {
    visualize: { fn: "count" },
    groupBy: null,
    sampleSort: { by: schema.timeField, dir: "desc" },
    groupSort: { by: "value", dir: "desc" },
    chart: "bar",
    interval: null,
  }
}

/** Repairs a query against the schema so a stale field key never reaches the views. */
export function normalizeQuery(query: AggregateQuery, schema: FieldSchema): AggregateQuery {
  const base = defaultQuery(schema)
  const groupField = fieldByKey(schema, query.groupBy)
  const groupBy = groupField?.kind === "text" ? groupField.key : null
  const sampleSort = fieldByKey(schema, query.sampleSort?.by)
    ? query.sampleSort
    : base.sampleSort
  const redundant =
    (query.groupSort?.by === "group" && groupBy === null) ||
    (query.groupSort?.by === "count" && query.visualize?.fn === "count")
  const groupSort = query.groupSort && !redundant ? query.groupSort : base.groupSort
  const interval =
    typeof query.interval === "number" && query.interval > 0 && Number.isFinite(query.interval)
      ? query.interval
      : null
  return {
    visualize: coerceVisualize(query.visualize ?? base.visualize, schema),
    groupBy,
    sampleSort,
    groupSort,
    chart: query.chart === "line" ? "line" : "bar",
    interval,
  }
}

export function sameQuery(a: AggregateQuery, b: AggregateQuery): boolean {
  return JSON.stringify(a) === JSON.stringify(b)
}

/** The row's value when it is a finite number, otherwise null. */
export function numberAt(row: AggregateRow, key: string): number | null {
  const value = row[key]
  return typeof value === "number" && Number.isFinite(value) ? value : null
}

/** Largest magnitude a JavaScript Date can hold; a timestamp beyond it cannot be formatted. */
const MAX_TIME = 8.64e15

/** The row's value when it is a timestamp a Date can represent, otherwise null (a missing time). */
export function timeAt(row: AggregateRow, key: string): number | null {
  const value = numberAt(row, key)
  return value !== null && Math.abs(value) <= MAX_TIME ? value : null
}

/** Linear interpolation between ranks; `sorted` ascending, `p` from 0 to 1. */
export function percentile(sorted: number[], p: number): number | null {
  if (sorted.length === 0) return null
  const position = Math.min(1, Math.max(0, p)) * (sorted.length - 1)
  const low = Math.floor(position)
  const high = Math.ceil(position)
  return sorted[low] + (sorted[high] - sorted[low]) * (position - low)
}

/** What a bucket or group with no values shows: zero for additive counts, null (a gap) for the rest. */
export function emptyValue(fn: AggregateFn): number | null {
  return fn === "count" || fn === "count_unique" || fn === "sum" ? 0 : null
}

export function aggregateValue(
  rows: AggregateRow[],
  visualize: Visualize
): number | null {
  const { fn, field } = visualize
  if (fn === "count") return rows.length
  if (!field) return emptyValue(fn)
  if (fn === "count_unique") {
    const seen = new Set<string>()
    for (const row of rows) {
      const value = row[field]
      if (value !== null && value !== undefined && value !== "") seen.add(String(value))
    }
    return seen.size
  }
  const values: number[] = []
  for (const row of rows) {
    const value = numberAt(row, field)
    if (value !== null) values.push(value)
  }
  if (values.length === 0) return emptyValue(fn)
  if (fn === "sum") return values.reduce((a, b) => a + b, 0)
  if (fn === "avg") return values.reduce((a, b) => a + b, 0) / values.length
  if (fn === "min") return Math.min(...values)
  if (fn === "max") return Math.max(...values)
  values.sort((a, b) => a - b)
  return percentile(values, Number(fn.slice(1)) / 100)
}

/** Aggregates add up across groups, so a stacked bar total means something. */
export function isAdditive(fn: AggregateFn): boolean {
  return fn === "count" || fn === "sum"
}

export function aggregateLabel(visualize: Visualize, schema: FieldSchema): string {
  if (visualize.fn === "count") return `count(${schema.rowLabel ?? "rows"})`
  return `${visualize.fn}(${visualize.field ?? ""})`
}

/** Unit of the aggregate's value: the field's own, except for the counts. */
export function aggregateUnit(visualize: Visualize, schema: FieldSchema): string | undefined {
  if (visualize.fn === "count" || visualize.fn === "count_unique") return undefined
  return fieldByKey(schema, visualize.field)?.unit
}

export type GroupRow<T extends AggregateRow = AggregateRow> = {
  /** Group value, or "" when there is no grouping. */
  key: string
  label: string
  value: number | null
  count: number
  /** Chart color slot, 0 to MAX_SERIES - 1; the last slot is "Other" when groups overflow. */
  slot: number
  rows: T[]
}

export function groupLabelOf(row: AggregateRow, key: string): string {
  const value = row[key]
  return value === null || value === undefined || value === "" ? NO_VALUE_LABEL : String(value)
}

/** Group key of the row: "" for a missing value, which no real value can equal, else the value as text. */
function groupKeyOf(row: AggregateRow, key: string): string {
  const value = row[key]
  return value === null || value === undefined ? "" : String(value)
}

/** Label of a group; a real value spelled like the missing-value label is quoted so the two stay apart. */
function groupLabelFor(key: string): string {
  if (key === "") return NO_VALUE_LABEL
  return key === NO_VALUE_LABEL ? `"${key}"` : key
}

function compareNullable(a: number | null, b: number | null, dir: SortDir): number {
  if (a === null && b === null) return 0
  if (a === null) return 1
  if (b === null) return -1
  return dir === "asc" ? a - b : b - a
}

/** One row per group value (a single "All rows" group without grouping), sorted by `query.groupSort`. */
export function buildGroups<T extends AggregateRow>(
  rows: T[],
  query: AggregateQuery
): GroupRow<T>[] {
  const buckets = new Map<string, T[]>()
  for (const row of rows) {
    const key = query.groupBy ? groupKeyOf(row, query.groupBy) : ""
    const list = buckets.get(key)
    if (list) list.push(row)
    else buckets.set(key, [row])
  }
  const { by, dir } = query.groupSort
  const groups = [...buckets].map(([key, members]) => ({
    key,
    label: query.groupBy ? groupLabelFor(key) : ALL_ROWS_LABEL,
    value: aggregateValue(members, query.visualize),
    count: members.length,
    slot: 0,
    rows: members,
  }))
  groups.sort((a, b) => {
    let order: number
    if (by === "group") order = a.label.localeCompare(b.label) * (dir === "asc" ? 1 : -1)
    else if (by === "count") order = compareNullable(a.count, b.count, dir)
    else order = compareNullable(a.value, b.value, dir)
    return order || a.label.localeCompare(b.label)
  })
  const overflow = groups.length > MAX_SERIES
  groups.forEach((group, index) => {
    group.slot = overflow ? Math.min(index, MAX_SERIES - 1) : index
  })
  return groups
}

export function sortSamples<T extends AggregateRow>(
  rows: T[],
  sort: AggregateQuery["sampleSort"],
  schema: FieldSchema
): T[] {
  const field = fieldByKey(schema, sort.by)
  const sorted = [...rows]
  const sign = sort.dir === "asc" ? 1 : -1
  sorted.sort((a, b) => {
    let order = 0
    if (field?.kind === "text") {
      order = groupLabelOf(a, sort.by).localeCompare(groupLabelOf(b, sort.by)) * sign
    } else if (field) {
      order = compareNullable(numberAt(a, sort.by), numberAt(b, sort.by), sort.dir)
    }
    return order || a.id.localeCompare(b.id)
  })
  return sorted
}

export function maxOf(rows: AggregateRow[], key: string): number {
  let max = 0
  for (const row of rows) max = Math.max(max, numberAt(row, key) ?? 0)
  return max
}

export function bucketStart(time: number, interval: number): number {
  return Math.floor(time / interval) * interval
}

function bucketsBetween(min: number, max: number, interval: number): number {
  return Math.floor(max / interval) - Math.floor(min / interval) + 1
}

/**
 * The bucket size to use for rows spanning `min` to `max`. Auto picks the smallest preset giving at
 * most AUTO_BUCKETS buckets; a requested size steps up through the presets until it gives at most
 * MAX_BUCKETS.
 */
export function resolveInterval(
  min: number,
  max: number,
  requested: number | null,
  presets: number[] = INTERVAL_PRESETS
): number {
  const limit = requested === null ? AUTO_BUCKETS : MAX_BUCKETS
  const from = requested ?? 0
  const candidates = presets.filter((preset) => preset >= from)
  if (requested !== null && !presets.includes(requested)) candidates.unshift(requested)
  for (const candidate of candidates) {
    if (bucketsBetween(min, max, candidate) <= limit) return candidate
  }
  return Math.max(DAY, Math.ceil((max - min + 1) / limit / DAY) * DAY)
}

/**
 * Tick values spanning zero: from a round minimum at or below `min` (zero when nothing is negative)
 * up to a round maximum at or above `max`.
 */
export function niceTicks(max: number, target = 4, min = 0): number[] {
  const top = Number.isFinite(max) ? Math.max(0, max) : 0
  const bottom = Number.isFinite(min) ? Math.min(0, min) : 0
  if (top === 0 && bottom === 0) return [0, 1]
  const raw = (top - bottom) / target
  const magnitude = 10 ** Math.floor(Math.log10(raw))
  const step =
    [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((candidate) => candidate >= raw) ??
    10 * magnitude
  const first = Math.floor(bottom / step + 1e-9)
  const last = Math.ceil(top / step - 1e-9)
  return Array.from({ length: last - first + 1 }, (_, i) => Number(((first + i) * step).toPrecision(12)))
}

export type ChartSeries = {
  key: string
  label: string
  slot: number
  values: (number | null)[]
}

export type ChartModel = {
  /** Start time of each bucket, ascending and continuous. */
  buckets: number[]
  interval: number
  series: ChartSeries[]
  yTicks: number[]
  /** First and last tick; the axis spans zero and every value. */
  yMin: number
  yMax: number
  stacked: boolean
  /** Rows that had a valid time and so landed in a bucket. */
  rowCount: number
  hasValues: boolean
}

/**
 * Buckets rows over time into one series per group slot. `groups` null (or a single group) draws
 * one series over all rows; otherwise each slot becomes a series, and slots shared by several
 * groups ("Other") re-aggregate the union of their rows. Null when no row has a valid time.
 */
export function buildChart<T extends AggregateRow>(
  rows: T[],
  query: AggregateQuery,
  schema: FieldSchema,
  groups: GroupRow<T>[] | null
): ChartModel | null {
  const timed = rows.filter((row) => timeAt(row, schema.timeField) !== null)
  if (timed.length === 0) return null
  let min = Infinity
  let max = -Infinity
  for (const row of timed) {
    const time = timeAt(row, schema.timeField) as number
    min = Math.min(min, time)
    max = Math.max(max, time)
  }
  const interval = resolveInterval(min, max, query.interval)
  const first = bucketStart(min, interval)
  const count = bucketsBetween(min, max, interval)
  const buckets = Array.from({ length: count }, (_, i) => first + i * interval)

  const sources: { key: string; label: string; slot: number; rows: T[] }[] = []
  if (!groups || groups.length <= 1) {
    sources.push({
      key: groups?.[0]?.key ?? "",
      label: groups?.[0]?.label ?? aggregateLabel(query.visualize, schema),
      slot: 0,
      rows: timed,
    })
  } else {
    const overflow = groups.length > MAX_SERIES
    for (const group of groups) {
      const isOther = overflow && group.slot === MAX_SERIES - 1
      const existing = sources.find((source) => source.slot === group.slot)
      if (existing) for (const row of group.rows) existing.rows.push(row)
      else
        sources.push({
          key: isOther ? "other" : group.key,
          label: isOther ? "Other" : group.label,
          slot: group.slot,
          rows: [...group.rows],
        })
    }
  }

  const series: ChartSeries[] = sources.map((source) => {
    const perBucket: T[][] = Array.from({ length: count }, () => [])
    for (const row of source.rows) {
      const time = timeAt(row, schema.timeField)
      if (time === null) continue
      perBucket[Math.floor(time / interval) - Math.floor(first / interval)].push(row)
    }
    return {
      key: source.key,
      label: source.label,
      slot: source.slot,
      values: perBucket.map((members) =>
        members.length === 0
          ? emptyValue(query.visualize.fn)
          : aggregateValue(members, query.visualize)
      ),
    }
  })

  const stacked = query.chart === "bar" && series.length > 1 && isAdditive(query.visualize.fn)
  let top = 0
  let bottom = 0
  for (let i = 0; i < count; i++) {
    if (stacked) {
      let above = 0
      let below = 0
      for (const s of series) {
        const value = s.values[i] ?? 0
        if (value >= 0) above += value
        else below += value
      }
      top = Math.max(top, above)
      bottom = Math.min(bottom, below)
    } else {
      for (const s of series) {
        top = Math.max(top, s.values[i] ?? 0)
        bottom = Math.min(bottom, s.values[i] ?? 0)
      }
    }
  }
  const yTicks = niceTicks(top, 4, bottom)
  return {
    buckets,
    interval,
    series,
    yTicks,
    yMin: yTicks[0],
    yMax: yTicks[yTicks.length - 1],
    stacked,
    rowCount: timed.length,
    hasValues: series.some((s) => s.values.some((value) => value !== null)),
  }
}

export function formatNumber(value: number): string {
  const abs = Math.abs(value)
  const trim = (n: number) => Number(n.toFixed(1)).toString()
  if (abs >= 1_000_000) return `${trim(value / 1_000_000)}M`
  if (abs >= 10_000) return `${trim(value / 1000)}k`
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: abs >= 100 ? 0 : abs >= 10 ? 1 : 2,
  }).format(value)
}

export function formatValue(value: number | null, unit?: string): string {
  if (value === null) return "—"
  return unit ? `${formatNumber(value)} ${unit}` : formatNumber(value)
}

export function formatInterval(interval: number): string {
  if (interval % DAY === 0) return interval === DAY ? "1 day" : `${interval / DAY} days`
  if (interval % HOUR === 0) return interval === HOUR ? "1 hour" : `${interval / HOUR} hours`
  const minutes = interval / MINUTE
  return minutes === 1 ? "1 minute" : `${Number(minutes.toFixed(1))} minutes`
}

const DAY_FORMAT = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const CLOCK_FORMAT = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23",
})

/** "Oct 21" for day buckets; a clock time otherwise, with the date added when `withDate`. */
export function formatBucket(time: number, interval: number, withDate: boolean): string {
  const date = new Date(time)
  if (interval >= DAY) return DAY_FORMAT.format(date)
  const clock = CLOCK_FORMAT.format(date)
  return withDate ? `${DAY_FORMAT.format(date)} ${clock}` : clock
}

/** "Oct 21 14:05"; a dash for a timestamp a Date cannot represent. */
export function formatDateTime(time: number): string {
  const date = new Date(time)
  if (Number.isNaN(date.getTime())) return "—"
  return `${DAY_FORMAT.format(date)} ${CLOCK_FORMAT.format(date)}`
}

import { useState } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"
import { useCollection } from "@/lib/mini/store"

import { AggregateBuilder } from "./aggregate-builder"
import type { FieldSchema } from "./types"

type Delivery = {
  id: string
  timestamp: number
  courier: string
  zone: string
  vehicle: string
  minutes: number
  km: number
  items: number
}

const SCHEMA: FieldSchema = {
  fields: [
    { key: "timestamp", label: "Time", kind: "time" },
    { key: "courier", label: "Courier", kind: "text" },
    { key: "zone", label: "Zone", kind: "text" },
    { key: "vehicle", label: "Vehicle", kind: "text" },
    { key: "minutes", label: "Minutes", kind: "number", unit: "min" },
    { key: "km", label: "Distance", kind: "number", unit: "km" },
    { key: "items", label: "Items", kind: "number" },
  ],
  timeField: "timestamp",
  barField: "minutes",
  rowLabel: "deliveries",
}

const HOUR = 3_600_000
const COURIERS = [
  { name: "Mika", vehicle: "bike" },
  { name: "Tobias", vehicle: "van" },
  { name: "Ines", vehicle: "scooter" },
  { name: "Oren", vehicle: "bike" },
  { name: "Sade", vehicle: "van" },
  { name: "Lucan", vehicle: "scooter" },
]
const ZONES = [
  { name: "Harbor", minutes: 22, km: 2.4 },
  { name: "Old Town", minutes: 27, km: 3.1 },
  { name: "Riverside", minutes: 31, km: 4.2 },
  { name: "Uptown", minutes: 35, km: 5.0 },
  { name: "Hillcrest", minutes: 41, km: 6.3 },
]
// relative order volume by hour of day: quiet nights, a lunch bump and a dinner peak
const HOUR_WEIGHT = [
  1, 1, 0, 0, 0, 1, 2, 3, 4, 4, 5, 8, 10, 8, 5, 4, 5, 8, 12, 12, 9, 6, 3, 2,
]

function mulberry32(seed: number) {
  let a = seed
  return () => {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function buildSeed(): Delivery[] {
  const random = mulberry32(7)
  const end = Math.floor(Date.now() / HOUR) * HOUR
  const start = end - 48 * HOUR
  const hours: number[] = []
  for (let t = start; t < end; t += HOUR) {
    const weight = HOUR_WEIGHT[new Date(t).getHours()]
    for (let i = 0; i < weight * 2; i++) hours.push(t)
  }
  const rows = Array.from({ length: 1400 }, (_, index): Delivery => {
    const hour = hours[Math.floor(random() * hours.length)]
    const zone = ZONES[Math.floor(random() * ZONES.length)]
    const courier = COURIERS[Math.floor(random() * COURIERS.length)]
    const busy = HOUR_WEIGHT[new Date(hour).getHours()] >= 10 ? 1.4 : 1
    const spike = random() < 0.05 ? 2 + random() * 1.5 : 1
    const speed = courier.vehicle === "bike" ? 1.1 : courier.vehicle === "van" ? 0.95 : 1
    const minutes = zone.minutes * busy * spike * speed * (0.75 + random() * 0.5)
    return {
      id: `DL-${String(index + 1).padStart(4, "0")}`,
      timestamp: hour + Math.floor(random() * HOUR),
      courier: courier.name,
      zone: zone.name,
      vehicle: courier.vehicle,
      minutes: Math.round(minutes * 10) / 10,
      km: Math.round(zone.km * (0.7 + random() * 0.6) * 10) / 10,
      items: 1 + Math.floor(random() * 8),
    }
  })
  rows.sort((a, b) => a.timestamp - b.timestamp)
  return rows.map((row, i) => ({ ...row, id: `DL-${String(i + 1).padStart(4, "0")}` }))
}

type Preview = "live" | "empty" | "loading" | "error"
const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]
const PREVIEW_ERROR = new Error("The sample delivery log could not be read.")

export default function Demo() {
  const [seed] = useState(buildSeed)
  const store = useCollection<Delivery>("aggregate-builder-demo", seed)
  const [preview, setPreview] = useState<Preview>("live")
  const [opened, setOpened] = useState<Delivery | null>(null)

  const status =
    preview === "loading" || preview === "error"
      ? preview
      : store.status === "ready" || preview === "empty"
        ? "ready"
        : store.status
  const rows = preview === "empty" ? [] : store.items

  const restore = async () => {
    try {
      await store.replaceAll(buildSeed())
      setPreview("live")
    } catch (cause) {
      toast.error("Couldn't reset the sample deliveries", {
        description: cause instanceof Error ? cause.message : String(cause),
      })
    }
  }

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">State preview (demo only)</span>
        <div role="group" aria-label="State preview" className="flex gap-1">
          {PREVIEWS.map((name) => (
            <Button
              key={name}
              size="xs"
              variant={preview === name ? "default" : "outline"}
              aria-pressed={preview === name}
              onClick={() => {
                setPreview(name)
                setOpened(null)
              }}
              className="capitalize"
            >
              {name}
            </Button>
          ))}
        </div>
        <Button size="xs" variant="ghost" className="ml-auto" onClick={() => void restore()}>
          Reset sample data
        </Button>
      </div>

      <div className="min-h-[34rem] flex-1 overflow-hidden rounded-lg border">
        <AggregateBuilder
          rows={rows}
          schema={SCHEMA}
          status={status}
          error={preview === "error" ? PREVIEW_ERROR : store.error}
          onRetry={() => setPreview("live")}
          onOpenRow={setOpened}
          emptyTitle="No deliveries to chart"
          emptyAction={{ label: "Restore sample deliveries", onClick: () => void restore() }}
          aria-label="Delivery times"
        />
      </div>

      <p role="status" className="min-h-4 text-xs text-muted-foreground">
        {opened
          ? `${opened.id}: ${opened.courier} by ${opened.vehicle} to ${opened.zone}, ${opened.minutes} min, ${opened.km} km, ${opened.items} items.`
          : ""}
      </p>

      <p className="text-xs text-muted-foreground">
        Keys: v aggregate, g group by (Aggregates tab), s sort by, 1 Samples, 2 Aggregates, c line or
        bar. On the chart: Left and Right move the cursor, Home and End jump, Esc clears. Click a
        column header to sort by it; click a delivery ID to open it.
      </p>
    </div>
  )
}

import type { KeyboardEvent, Ref } from "react"
import { ClockIcon, HashIcon, TypeIcon } from "lucide-react"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"

import type { FieldKind } from "./types"

export const NONE_VALUE = "__none"

/** Keys the block binds; a focused picker must not treat them as typeahead. */
export const BLOCK_KEYS = new Set(["v", "g", "s", "c", "1", "2"])

export function keepBlockKeys(event: KeyboardEvent<HTMLElement>) {
  if (event.ctrlKey || event.metaKey || event.altKey) return
  if (BLOCK_KEYS.has(event.key.toLowerCase())) event.preventDefault()
}

export type FieldOption = {
  value: string
  label: string
  kind?: FieldKind
}

const KIND_ICONS = { number: HashIcon, text: TypeIcon, time: ClockIcon }

function OptionLabel({ option }: { option: FieldOption }) {
  const Icon = option.kind ? KIND_ICONS[option.kind] : null
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      {Icon ? <Icon className="size-3 shrink-0 text-muted-foreground" aria-hidden /> : null}
      <span className="truncate">{option.label}</span>
    </span>
  )
}

/**
 * A select over named fields (or any short list of options), with a kind icon per option, an
 * optional "None" choice that reports `null`, and a disabled state.
 */
export function FieldPicker({
  id,
  label,
  value,
  onChange,
  options,
  noneLabel,
  disabled,
  placeholder,
  triggerRef,
  className,
}: {
  id?: string
  /** Accessible name; the rail also pairs a visible heading with it. */
  label: string
  value: string | null
  onChange: (value: string | null) => void
  options: FieldOption[]
  /** Adds a first choice with this label that selects no field. */
  noneLabel?: string
  disabled?: boolean
  placeholder?: string
  triggerRef?: Ref<HTMLButtonElement>
  className?: string
}) {
  const current = value ?? (noneLabel ? NONE_VALUE : undefined)
  return (
    <Select
      value={current}
      onValueChange={(next) => onChange(next === NONE_VALUE ? null : next)}
      disabled={disabled}
    >
      <SelectTrigger
        id={id}
        ref={triggerRef}
        size="sm"
        aria-label={label}
        onKeyDown={keepBlockKeys}
        className={cn("w-full min-w-0", className)}
      >
        <SelectValue placeholder={placeholder ?? "Pick a field"} />
      </SelectTrigger>
      <SelectContent>
        {noneLabel ? <SelectItem value={NONE_VALUE}>{noneLabel}</SelectItem> : null}
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            <OptionLabel option={option} />
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

import type { Ref } from "react"
import { RotateCcwIcon } from "lucide-react"

import { Button } from "@/components/ui/button"

import { AggregatePicker } from "./aggregate-picker"
import {
  aggregateLabel,
  availableAggregates,
  coerceVisualize,
  fieldByKey,
  fieldsFor,
} from "./aggregate"
import { FieldPicker, type FieldOption } from "./field-picker"
import type {
  AggregateFn,
  AggregateQuery,
  FieldSchema,
  GroupSortBy,
  ResultsTab,
  SortDir,
} from "./types"

const ROWS_VALUE = "__rows"

const DIRECTIONS: FieldOption[] = [
  { value: "desc", label: "Desc" },
  { value: "asc", label: "Asc" },
]

function Heading({ id, children }: { id: string; children: string }) {
  return (
    <h3 id={id} className="mb-1.5 text-xs font-medium text-foreground">
      {children}
    </h3>
  )
}

/**
 * The left rail: Visualize (aggregate and field), Group By and Sort By. Edits go out as patches to
 * the query; `tab` decides which sort the Sort By controls edit and whether Group By applies.
 */
export function QueryRail({
  schema,
  query,
  tab,
  disabled,
  canReset,
  onChange,
  onReset,
  aggregateRef,
  groupRef,
  sortRef,
}: {
  schema: FieldSchema
  query: AggregateQuery
  tab: ResultsTab
  disabled?: boolean
  canReset: boolean
  onChange: (patch: Partial<AggregateQuery>) => void
  onReset: () => void
  aggregateRef?: Ref<HTMLButtonElement>
  groupRef?: Ref<HTMLButtonElement>
  sortRef?: Ref<HTMLButtonElement>
}) {
  const { visualize } = query
  const fieldOptions = fieldsFor(visualize.fn, schema).map<FieldOption>((field) => ({
    value: field.key,
    label: field.label,
    kind: field.kind,
  }))
  const rowLabel = schema.rowLabel ?? "rows"
  const groupFields = schema.fields
    .filter((field) => field.kind === "text")
    .map<FieldOption>((field) => ({ value: field.key, label: field.label, kind: "text" }))
  const groupingApplies = tab === "aggregates"
  const groupField = fieldByKey(schema, query.groupBy)

  let sortOptions: FieldOption[]
  let sortBy: string
  let sortDir: SortDir
  if (tab === "samples") {
    sortOptions = schema.fields.map((field) => ({
      value: field.key,
      label: field.label,
      kind: field.kind,
    }))
    sortBy = query.sampleSort.by
    sortDir = query.sampleSort.dir
  } else {
    sortOptions = [{ value: "value", label: aggregateLabel(visualize, schema) }]
    if (visualize.fn !== "count") {
      sortOptions.push({ value: "count", label: `count(${rowLabel})` })
    }
    if (groupField) sortOptions.push({ value: "group", label: groupField.label })
    sortBy = query.groupSort.by
    sortDir = query.groupSort.dir
  }

  const changeAggregate = (fn: AggregateFn) =>
    onChange({ visualize: coerceVisualize({ fn, field: visualize.field }, schema) })

  const changeSort = (patch: { by?: string; dir?: SortDir }) => {
    if (tab === "samples") {
      onChange({ sampleSort: { ...query.sampleSort, ...patch } })
    } else {
      onChange({
        groupSort: {
          by: (patch.by as GroupSortBy | undefined) ?? query.groupSort.by,
          dir: patch.dir ?? query.groupSort.dir,
        },
      })
    }
  }

  return (
    <div className="flex flex-col gap-5 p-3" role="group" aria-label="Query">
      <section aria-labelledby="aggregate-builder-visualize">
        <Heading id="aggregate-builder-visualize">Visualize</Heading>
        <div className="grid grid-cols-2 gap-2">
          <AggregatePicker
            value={visualize.fn}
            onChange={changeAggregate}
            options={availableAggregates(schema)}
            disabled={disabled}
            triggerRef={aggregateRef}
          />
          {visualize.fn === "count" ? (
            <FieldPicker
              label="Field"
              value={ROWS_VALUE}
              onChange={() => {}}
              options={[{ value: ROWS_VALUE, label: rowLabel }]}
              disabled
            />
          ) : (
            <FieldPicker
              label="Field"
              value={visualize.field ?? null}
              onChange={(field) =>
                onChange({ visualize: { fn: visualize.fn, field: field ?? undefined } })
              }
              options={fieldOptions}
              disabled={disabled}
            />
          )}
        </div>
      </section>

      <section aria-labelledby="aggregate-builder-group">
        <Heading id="aggregate-builder-group">Group by</Heading>
        <FieldPicker
          label="Group by field"
          value={query.groupBy}
          onChange={(field) => onChange({ groupBy: field })}
          options={groupFields}
          noneLabel="None"
          disabled={disabled || !groupingApplies}
          triggerRef={groupRef}
        />
        {groupingApplies ? null : (
          <p className="mt-1 text-xs text-muted-foreground">
            Samples are not grouped. Switch to Aggregates to group.
          </p>
        )}
      </section>

      <section aria-labelledby="aggregate-builder-sort">
        <Heading id="aggregate-builder-sort">Sort by</Heading>
        <div className="grid grid-cols-[minmax(0,1fr)_5rem] gap-2">
          <FieldPicker
            label="Sort by field"
            value={sortBy}
            onChange={(by) => by && changeSort({ by })}
            options={sortOptions}
            disabled={disabled}
            triggerRef={sortRef}
          />
          <FieldPicker
            label="Sort direction"
            value={sortDir}
            onChange={(dir) => dir && changeSort({ dir: dir as SortDir })}
            options={DIRECTIONS}
            disabled={disabled}
          />
        </div>
      </section>

      {canReset ? (
        <Button variant="outline" size="sm" onClick={onReset} className="self-start">
          <RotateCcwIcon aria-hidden />
          Reset
        </Button>
      ) : null}
    </div>
  )
}

